<?php
require __DIR__.'/config.php';manager_only();$month=guard_month();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_post();$action=post('action');$month=post('bulan');if(!valid_month($month))$month=date('Y-m');
 $imamId=(int)post('imam_id');$amount=post('amount');
 try{
  $ch=db()->prepare('SELECT COUNT(*) FROM imams WHERE id=?');$ch->execute([$imamId]);
  if(!$ch->fetchColumn())throw new RuntimeException('Imam tidak ditemukan.');
  if(!preg_match('/^\d{1,10}$/',$amount)||($nominal=(int)$amount)<=0||$nominal>1000000000)throw new RuntimeException('Nominal wajib lebih dari nol dan maksimal 1 miliar.');
  if($action==='adjust'){$kind=post('kind');$note=post('note');if(!in_array($kind,['tambahan','potongan'],true)||mb_strlen($note)<4)throw new RuntimeException('Pilih jenis penyesuaian dan isi keterangan minimal 4 karakter.');$q=db()->prepare('INSERT INTO honor_adjustments (imam_id,month,kind,amount,note,created_by) VALUES (?,?,?,?,?,?)');$q->execute([$imamId,$month.'-01',$kind,$nominal,mb_substr($note,0,255),user()['id']]);audit('penyesuaian_bisyaroh',$month.' · Imam #'.$imamId.' · '.$kind.' '.money($nominal));notice('Penyesuaian berhasil dicatat.');}
  elseif($action==='pay'){$e=earnings($month,$imamId);if($nominal>$e['balance'])throw new RuntimeException('Pembayaran melebihi sisa bisyaroh yang tercatat.');$q=db()->prepare('INSERT INTO honor_payments (imam_id,month,amount,paid_at,note,created_by) VALUES (?,?,?,NOW(),?,?)');$q->execute([$imamId,$month.'-01',$nominal,mb_substr(post('note'),0,255),user()['id']]);audit('pembayaran_bisyaroh',$month.' · Imam #'.$imamId.' · '.money($nominal));notice('Pembayaran berhasil dicatat.');}
  else throw new RuntimeException('Aksi tidak valid.');
 }catch(RuntimeException $e){notice($e->getMessage(),'danger');}catch(PDOException $e){notice('Penyimpanan gagal.','danger');}
 go('rekap.php',['bulan'=>$month]);
}
$imams=all_imams();$stats=[];foreach($imams as $i)$stats[$i['id']]=earnings($month,(int)$i['id']);
$qs=db()->prepare('SELECT a.*,i.name imam_name FROM honor_adjustments a JOIN imams i ON i.id=a.imam_id WHERE a.month=? ORDER BY a.created_at DESC,a.id DESC');$qs->execute([$month.'-01']);$adjustments=$qs->fetchAll();
$qs=db()->prepare('SELECT p.*,i.name imam_name FROM honor_payments p JOIN imams i ON i.id=p.imam_id WHERE p.month=? ORDER BY p.paid_at DESC,p.id DESC');$qs->execute([$month.'-01']);$payments=$qs->fetchAll();
if(queryv('format')==='csv'){
 header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="rekap-bisyaroh-'.$month.'.csv"');$o=fopen('php://output','wb');fwrite($o,"\xEF\xBB\xBF");fputcsv($o,['Imam','Penugasan','Bersedia','Tidak Bisa','Hadir','Dasar','Tambahan','Potongan','Total Berjalan','Sudah Dibayar','Sisa']);
 foreach($imams as $i){$s=$stats[$i['id']];fputcsv($o,array_map('csvsafe',[$i['name'],$s['total'],$s['confirmed'],$s['unavailable'],$s['hadir'],$s['base'],$s['bonus'],$s['deduction'],$s['net'],$s['paid'],$s['balance']]));}fclose($o);exit;
}
$pageTitle='Rekap bisyaroh';$active='rekap';require __DIR__.'/partials/admin_header.php';
?>
<div class="page-head"><div><div class="section-eyebrow">RINGKASAN HONOR IMAM</div><h1>Rekap bisyaroh <?=h(month_label($month))?></h1><p>Rincian penghasilan, tambahan, potongan, dan pembayaran imam.</p></div><div class="action-row"><a class="btn outline" href="<?=h(link_to('rekap.php',['bulan'=>$month,'format'=>'csv']))?>">Unduh CSV</a><button type="button" onclick="window.print()" class="btn outline">Cetak</button></div></div><div class="card"><form method="get" class="filter-panel"><label>Periode<input type="month" name="bulan" value="<?=h($month)?>"></label><button class="btn primary">Tampilkan</button></form><div class="table-scroll"><table class="data-table"><thead><tr><th>Nama imam</th><th>Jadwal</th><th>Bersedia</th><th>Tidak bisa</th><th>Hadir</th><th>Dasar</th><th>Tambahan</th><th>Potongan</th><th>Total berjalan</th><th>Dibayar</th><th>Sisa</th></tr></thead><tbody><?php foreach($imams as $i):$s=$stats[$i['id']];?><tr><td><b><?=h($i['name'])?></b></td><td><?=$s['total']?></td><td><?=$s['confirmed']?></td><td><?=$s['unavailable']?></td><td><?=$s['hadir']?></td><td><?=h(money($s['base']))?></td><td><?=h(money($s['bonus']))?></td><td><?=h(money($s['deduction']))?></td><td class="money-green"><?=h(money($s['net']))?></td><td><?=h(money($s['paid']))?></td><td><b><?=h(money($s['balance']))?></b></td></tr><?php endforeach;?></tbody></table></div><p class="help mt16">Total berjalan belum final sampai seluruh konfirmasi, absensi, dan koreksi periode selesai. Perhitungan: dasar + (tugas ekstra yang dikonfirmasi × tarif tambahan) + tambahan manual − (penugasan yang dijawab tidak bisa × tarif potongan) − potongan manual. Tidak otomatis menjadikan jawaban "bisa" sebagai hadir.</p></div>
<div class="admin-columns"><div class="column"><section class="card"><h2>Penyesuaian manual bisyaroh</h2><p class="caption">Tambahkan koreksi jika ada keputusan pengurus.</p><form method="post" class="form-grid mt16"><?=csrf_input()?><input type="hidden" name="bulan" value="<?=h($month)?>"><input type="hidden" name="action" value="adjust"><label>Nama imam<select name="imam_id" required><?php foreach($imams as $i):?><option value="<?=h($i['id'])?>"><?=h($i['name'])?></option><?php endforeach;?></select></label><label>Jenis<select name="kind"><option value="tambahan">Tambahan</option><option value="potongan">Potongan</option></select></label><label>Nominal (Rp)<input name="amount" type="number" min="1" max="1000000000" required></label><label>Keterangan<input name="note" required minlength="4" maxlength="255" placeholder="Contoh: pengganti imam"></label><div class="admin-form-actions"><button class="btn primary">Catat penyesuaian</button></div></form><div class="divider"></div><h3>Riwayat penyesuaian</h3><div class="table-scroll"><table class="data-table"><thead><tr><th>Imam</th><th>Jenis</th><th>Nominal</th><th>Keterangan</th></tr></thead><tbody><?php foreach($adjustments as $a):?><tr><td><?=h($a['imam_name'])?></td><td><?=h(ucfirst($a['kind']))?></td><td><?=h(money($a['amount']))?></td><td><?=h($a['note'])?></td></tr><?php endforeach;?><?php if(!$adjustments):?><tr><td colspan="4" class="empty">Belum ada penyesuaian.</td></tr><?php endif;?></tbody></table></div></section></div>
<div class="column"><section class="card"><h2>Catat pembayaran bisyaroh</h2><p class="caption">Pembayaran dapat dicatat sebagian, dengan batas sisa berjalan.</p><form method="post" class="form-grid mt16"><?=csrf_input()?><input type="hidden" name="bulan" value="<?=h($month)?>"><input type="hidden" name="action" value="pay"><label class="full">Nama imam<select name="imam_id" required><?php foreach($imams as $i):?><option value="<?=h($i['id'])?>"><?=h($i['name'])?> (sisa <?=h(money($stats[$i['id']]['balance']))?>)</option><?php endforeach;?></select></label><label class="full">Nominal pembayaran (Rp)<input name="amount" type="number" min="1" max="1000000000" required></label><label class="full">Catatan (opsional)<input name="note" maxlength="255" placeholder="Contoh: transfer tanggal 30"></label><div class="admin-form-actions"><button class="btn primary">Simpan pembayaran</button></div></form><div class="divider"></div><h3>Riwayat pembayaran</h3><div class="table-scroll"><table class="data-table"><thead><tr><th>Imam</th><th>Tanggal</th><th>Jumlah</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><?=h($p['imam_name'])?></td><td><?=h(substr($p['paid_at'],0,10))?></td><td><?=h(money($p['amount']))?></td></tr><?php endforeach;?><?php if(!$payments):?><tr><td colspan="3" class="empty">Belum ada pembayaran.</td></tr><?php endif;?></tbody></table></div></section></div></div>
<?php require __DIR__.'/partials/admin_footer.php'; ?>
